using System.Text.Json;
using ExtractorTester.Config;

namespace ExtractorTester.Tests;

/// <summary>Fixtures/Compare/compare_cases.json, generated by gen_compare_fixtures.py from the Python comparers.</summary>
internal static class CompareFixtures
{
    private static readonly Lazy<JsonDocument> Doc = new(() => JsonDocument.Parse(File.ReadAllBytes(
        Path.Combine(AppContext.BaseDirectory, "Fixtures", "Compare", "compare_cases.json"))));

    public static IEnumerable<JsonElement> Cases(string kind) => Doc.Value.RootElement.GetProperty(kind).EnumerateArray();

    public static JsonElement Case(string kind, string name) => Cases(kind).Single(c => c.GetProperty("name").GetString() == name);

    public static IEnumerable<object[]> Names(string kind) => Cases(kind).Select(c => new object[] { c.GetProperty("name").GetString()! });

    /// <summary>test_text._cfg / test_buffered._cfg with the case's overrides.</summary>
    public static CompareConfig TextConfig(JsonElement overrides) =>
        Apply(new CompareConfig { NameField = "name", MimePrimaryField = "a", MimeSecondaryField = "b" }, overrides);

    /// <summary>test_compare_fields.cfg with the case's overrides.</summary>
    public static CompareConfig FieldConfig(JsonElement overrides) =>
        Apply(
            new CompareConfig
            {
                NameField = "n",
                MimePrimaryField = "mp",
                MimeSecondaryField = "ms",
                GenericFields = ["meta"],
                IgnoreFields = ["skip"],
            },
            overrides);

    private static CompareConfig Apply(CompareConfig cfg, JsonElement overrides)
    {
        foreach (var p in overrides.EnumerateObject())
        {
            switch (p.Name)
            {
                case "containment_pct": cfg.ContainmentPct = p.Value.GetDouble(); break;
                case "snippet_chars": cfg.SnippetChars = p.Value.GetInt64(); break;
                case "full_compare_max_chars": cfg.FullCompareMaxChars = p.Value.GetInt64(); break;
                case "max_block_chars": cfg.MaxBlockChars = p.Value.GetInt64(); break;
                default: throw new ArgumentException($"unmapped config key {p.Name}");
            }
        }
        cfg.ApplyPostInit();
        return cfg;
    }
}
